from scipy.optimize import least_squares
e=df['eps'].values;t=df['T'].values;s=df['sigma'].values
forms={
 'log': lambda p: p[0]*np.log(1+p[1]*e)+p[2]*e,
 'rat': lambda p: p[0]*e/(1+p[1]*e)+p[2]*e,
 'sqrt': lambda p: p[0]*np.sqrt(e)/(1+p[1]*np.sqrt(e))+p[2]*e,
 'pow': lambda p: p[0]*e**p[1]/(1+p[2]*e**p[1]),
 'vocexp': lambda p: p[0]*(1-np.exp(-p[1]*e**p[2]))+p[3]*e,
 'tanh': lambda p: p[0]*np.tanh(p[1]*e**p[2])+p[3]*e,
}
for k,f in forms.items():
    best=None
    for st in [0.5,1,2]:
        try:
            r=least_squares(lambda p: f(p)-s, np.array([10,st,0.5,0.1]))
            n=np.mean(r.fun**2)/np.var(s)
            if best is None or n<best[0]: best=(n,np.round(r.x,4))
        except Exception as ex: pass
    print(k,best)
